package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.nio.file.*;
import static org.junit.Assert.*;

public class MetricObservationStoreTest {
    @Test public void immutableClocksCameraBindingsAndChecksumSurviveRestart()throws Exception{
        var root=Files.createTempDirectory("metric037-control-");var ledger=new WorldLedger(root);String world=ledger.create(WorldLedgerTest.source(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0)),"Metric control").getString("id");
        try(var o=new WorldObservationStore(root,ledger)){var m=new MetricObservationStore(root,o,ledger);var d=WorldObservationStoreTest.importPack(o,WorldObservationStoreTest.pack());var clock=new JSONObject().put("datasetId",d.getString("id")).put("seconds",new JSONArray("[0,.1,.21,.3,.42,.5,.61,.7,.83]")).put("source","Explicit synthetic irregular timestamps; not camera measurement").put("cameraKey","test-fixed");m.clock(clock);assertThrows(IllegalStateException.class,()->m.clock(WorldFrames.copy(clock).put("source","rewritten")));assertThrows(IllegalArgumentException.class,()->m.clock(WorldFrames.copy(clock).put("seconds",new JSONArray("[0,.1,.1,.3,.4,.5,.6,.7,.8]"))));var run=WorldObservationStoreTest.settled(o,o.start(WorldObservationStoreTest.arguments(ledger,world,d,0)).getString("id"));var def=PlaneCalibrationTest.mat();def.put("imagePoints",new JSONArray("[[0,0],[1,0],[1,1],[0,1]]"));var g=m.geometry(def);var req=new JSONObject().put("runId",run.getString("id")).put("geometryId",g.getString("id"));var before=ledger.observe(world);var v=m.view(req);assertEquals(8,v.getJSONArray("rows").length());assertTrue(v.getJSONArray("rows").getJSONObject(0).has("positionM"));assertTrue(before.similar(ledger.observe(world)));var wrong=m.geometry(WorldFrames.copy(def).put("cameraKey","another-camera"));assertThrows(IllegalStateException.class,()->m.view(WorldFrames.copy(req).put("geometryId",wrong.getString("id"))));assertTrue(m.state().similar(new MetricObservationStore(root,o,ledger).state()));assertTrue(MetricReport.build(v).getJSONObject("files").getString("index.html").contains("Metres" )||MetricReport.build(v).getJSONObject("files").getString("index.html").contains("metres"));
            Path f=root.resolve("metric-observations/state.json");String bytes=Files.readString(f);Files.writeString(f,bytes.replace("metric-observations-037-v1","broken"));assertThrows(IllegalStateException.class,()->m.state());assertEquals(bytes.replace("metric-observations-037-v1","broken"),Files.readString(f));
        }
    }
    @Test public void fitAndHeldEvaluationDoNotChangeTrackingAndCannotUseSameRun()throws Exception{
        var root=Files.createTempDirectory("metric037-fit-");var ledger=new WorldLedger(root);String world=ledger.create(WorldLedgerTest.source(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0)),"Metric fit control").getString("id");
        try(var o=new WorldObservationStore(root,ledger)){var m=new MetricObservationStore(root,o,ledger);var pack=WorldObservationStoreTest.pack();var frames=pack.getJSONArray("frames");for(int i=9;i<17;i++)frames.put(WorldFrames.copy(frames.getJSONObject(0)).put("sourceFrame",i));var d=WorldObservationStoreTest.importPack(o,pack);var seconds=new JSONArray();for(int i=0;i<17;i++)seconds.put(i*.1);m.clock(new JSONObject().put("datasetId",d.getString("id")).put("seconds",seconds).put("source","Synthetic control clock").put("cameraKey","test-fixed"));var def=PlaneCalibrationTest.mat().put("imagePoints",new JSONArray("[[0,0],[1,0],[1,1],[0,1]]"));String geo=m.geometry(def).getString("id");String run=o.start(WorldObservationStoreTest.arguments(ledger,world,d,0)).getString("id");var original=WorldObservationStoreTest.settled(o,run);var req=new JSONObject().put("runId",run).put("geometryId",geo);var v=m.view(req);var refs=new JSONArray();for(Object raw:v.getJSONArray("rows")){var r=(JSONObject)raw;refs.put(new JSONObject().put("ordinal",r.getInt("ordinal")).put("bodyId",r.getString("bodyId")).put("positionM",new JSONArray(new double[]{r.getJSONArray("positionM").getDouble(0)+.03,r.getJSONArray("positionM").getDouble(1)})));}var fit=m.fit(WorldFrames.copy(req).put("references",refs).put("source","Analytic offset test references, not real observations"));assertEquals(16,fit.getInt("referenceCount"));assertEquals(16,fit.getInt("rank"));assertTrue(original.similar(o.read(run)));assertThrows(IllegalStateException.class,()->m.fit(WorldFrames.copy(req).put("references",refs).put("source","repeated")));assertThrows(IllegalArgumentException.class,()->m.evaluate(WorldFrames.copy(req).put("profileId",fit.getString("id")).put("references",refs).put("source","same run")));
            int rev=o.state(world).getJSONObject("estimate").getInt("revision");String second=o.start(WorldObservationStoreTest.arguments(ledger,world,d,rev)).getString("id");WorldObservationStoreTest.settled(o,second);var eval=WorldFrames.copy(req).put("runId",second).put("profileId",fit.getString("id")).put("references",refs).put("source","Separate replay analytic control; not held real footage");assertTrue(m.evaluate(eval).getBoolean("passed"));assertThrows(IllegalStateException.class,()->m.evaluate(eval));assertTrue(original.similar(o.read(run)));}
    }
}
